function roundRobinIndex(counter, n) {
  return counter % n;
}

function leastLoadedIndex(loads) {
  let best = 0;
  for (let i = 1; i < loads.length; i++) {
    if (loads[i] < loads[best]) best = i;
  }
  return best;
}

function firstHealthyId(servers) {
  const found = servers.find((s) => s.healthy);
  return found ? found.id : null;
}

function totalWeight(servers) {
  return servers.reduce((sum, s) => sum + s.weight, 0);
}

function healthyIds(servers) {
  return servers.filter((s) => s.healthy).map((s) => s.id);
}

function shareOfTraffic(weight, weights) {
  const total = weights.reduce((a, b) => a + b, 0);
  return weight / total;
}

function pickRoundRobin(servers, cursor) {
  const n = servers.length;
  for (let i = 0; i < n; i++) {
    const index = (cursor + i) % n;
    if (servers[index].healthy) {
      return { id: servers[index].id, nextCursor: (index + 1) % n };
    }
  }
  return null;
}

function pickLeastConnections(servers) {
  let best = null;
  for (const s of servers) {
    if (!s.healthy) continue;
    if (best === null || s.active < best.active) best = s;
  }
  return best ? best.id : null;
}

function weightedSequence(servers) {
  const sequence = [];
  for (const s of servers) {
    for (let i = 0; i < s.weight; i++) sequence.push(s.id);
  }
  return sequence;
}
